84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
109	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
110	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        String address = normalizeAddress(owner.getAddress());
119	        if (address.isEmpty()) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        owner.setAddress(address);
123	        String telephone = toE164(owner.getTelephone());
124	        if (telephone == null) {
125	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	        }
127	        owner.setTelephone(telephone);
128	        if (owner.getEmail() != null) {
129	            String email = normalizeEmail(owner.getEmail());
130	            if (email == null) {
131	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
132	            }
133	            owner.setEmail(email);
134	        }
135	        if (owner.getPostcode() != null && !isValidPostcode(owner.getPostcode(), owner.getCity())) {
136	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
137	        }
138	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
139	        if (effectiveRegistrationDate == null) {
140	            effectiveRegistrationDate = LocalDate.now();
141	        }
142	        else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
143	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
144	        }
145	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
146	        owner.setRegistrationDate(registrationDate);
147	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
148	            return new ResponseEntity<>(HttpStatus.CONFLICT);
149	        }
150	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
151	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
152	        }
153	        // Owners sharing a household (same normalized last name and address) are given a
154	        // stable shared householdId, which forms the household component of the identityKey.
155	        String lastNameKey = householdKey(owner.getLastName());
156	        String addressKey = householdKey(owner.getAddress());
157	        List<Owner> householdMembers = new ArrayList<>();
158	        for (Owner existing : this.clinicService.findAllOwners()) {
159	            if (lastNameKey.equals(householdKey(existing.getLastName()))
160	                && addressKey.equals(householdKey(existing.getAddress()))) {
161	                householdMembers.add(existing);
162	            }
163	        }
164	        if (!householdMembers.isEmpty()) {
165	            String householdId = householdId(lastNameKey, addressKey);
166	            owner.setHouseholdId(householdId);
167	            for (Owner member : householdMembers) {
168	                if (!householdId.equals(member.getHouseholdId())) {
169	                    member.setHouseholdId(householdId);
170	                    this.clinicService.saveOwner(member);
171	                }
172	            }
173	        }
174	        // Consolidated duplicate detection: reject only when the whole identityKey
175	        // (normalized telephone | email | householdId) matches an existing owner's.
176	        String identityKey = identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
177	        for (Owner existing : this.clinicService.findAllOwners()) {
178	            if (identityKey.equals(identityKey(toE164(existing.getTelephone()),
179	                emailForKey(existing.getEmail()), existing.getHouseholdId()))) {
180	                return new ResponseEntity<>(HttpStatus.CONFLICT);
181	            }
182	        }
183	        owner.setCustomerCode(customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
184	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
185	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
186	        this.clinicService.saveOwner(owner);
187	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
188	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
189	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
190	            ownerDto.getMembershipLevel());
191	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
192	        headers.setLocation(UriComponentsBuilder.newInstance()
193	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
194	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
195	    }
