276	
277	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
278	    @Override
279	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
280	        Owner owner = this.clinicService.findOwnerById(ownerId);
281	        if (owner != null) {
282	            Pet pet = owner.getPet(petId);
283	            if (pet != null) {
284	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
285	            }
286	        }
287	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
288	    }
289	
290	    /**
291	     * The maximum number of owners permitted per city. Owner creation is rejected once the
292	     * owner's city already contains this many owners.
293	     */
294	    private static final int MAX_OWNERS_PER_CITY = 50;
295	
296	    /**
297	     * Counts how many existing owners live in the given city, compared case-insensitively.
298	     * This is evaluated before the new owner is persisted, so the owner being created is not
299	     * included in the count.
300	     *
301	     * @param city the new owner's city
302	     * @return the number of existing owners in that city
303	     */
304	    private int countOwnersInCity(String city) {
305	        int count = 0;
306	        for (Owner existing : this.clinicService.findAllOwners()) {
307	            if (city.equalsIgnoreCase(existing.getCity())) {
308	                count++;
309	            }
310	        }
311	        return count;
312	    }
313	
314	    /**
315	     * The maximum number of owners that may be created in a single business day. Owner
316	     * creation is rejected once this many owners already fall on the new owner's adjusted
317	     * business day {@code registrationDate}.
318	     */
319	    private static final int MAX_OWNERS_PER_DAY = 100;
320	
321	    /**
322	     * Rolls a date forward to the next business day: a Saturday or Sunday is moved forward
323	     * to the following Monday, while a weekday is returned unchanged.
324	     *
325	     * @param date the date to adjust
326	     * @return the same date if it is a weekday, otherwise the following Monday
327	     */
328	    private LocalDate toBusinessDay(LocalDate date) {
329	        DayOfWeek dayOfWeek = date.getDayOfWeek();
330	        if (dayOfWeek == DayOfWeek.SATURDAY) {
331	            return date.plusDays(2);
332	        }
333	        if (dayOfWeek == DayOfWeek.SUNDAY) {
334	            return date.plusDays(1);
335	        }
336	        return date;
337	    }
338	
339	    /**
340	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
341	     * registrationDate} rolls forward to the same business day. This is evaluated before the
342	     * new owner is persisted, so the owner being created is not included in the count.
343	     *
344	     * @param businessDay the adjusted business day to count against
345	     * @return the number of existing owners registered on that business day
346	     */
347	    private int countOwnersRegisteredOn(LocalDate businessDay) {
348	        int count = 0;
349	        for (Owner existing : this.clinicService.findAllOwners()) {
350	            LocalDate existingDate = existing.getRegistrationDate();
351	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
352	                count++;
353	            }
354	        }
355	        return count;
356	    }
357	
358	    /**
359	     * The number of owners that may be created on a single business day before a bulk-signup
360	     * warning is raised. Once more than this many owners already fall on the current business
361	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
362	     */
363	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
364	
365	    /**
366	     * Reports whether an unusually high number of owners have been created for today's business
367	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
368	     * the business day that {@code LocalDate.now()} rolls forward to.
369	     *
370	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
371	     */
372	    private boolean isBulkSignupDay() {
373	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
374	    }
375	
376	    /**
377	     * Builds the customer code for a newly created owner, formatted
378	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the canonical region
379	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
380	     * {@code "UNKNOWN"} when the postcode resolves no region) and {@code HASH8} is the
381	     * first eight upper-case hex characters of the SHA-256 digest of
382	     * {@code normalizedTelephone + lastName}. The code carries no sequence number, so it is
383	     * stable for a given telephone and last name rather than dependent on creation order.
384	     *
385	     * @param postcode            the owner's postcode (may be {@code null})
386	     * @param normalizedTelephone the owner's normalized E.164 telephone
387	     * @param lastName            the owner's last name
388	     * @return the assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
389	     */
390	    private static String customerCode(String postcode, String normalizedTelephone, String lastName) {
391	        String region = org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
392	        return region + "-" + sha256Hex8(normalizedTelephone + lastName);
393	    }
394	
395	    /**
396	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
397	     * bytes of {@code source} — the {@code HASH8} component of an owner's customer code.
398	     *
399	     * @param source the string to hash
400	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
401	     */
402	    private static String sha256Hex8(String source) {
403	        try {
404	            byte[] digest = MessageDigest.getInstance("SHA-256")
405	                .digest(source.getBytes(StandardCharsets.UTF_8));
406	            StringBuilder hex = new StringBuilder(digest.length * 2);
407	            for (byte b : digest) {
408	                hex.append(String.format("%02x", b));
409	            }
410	            return hex.substring(0, 8).toUpperCase();
411	        } catch (NoSuchAlgorithmException e) {
412	            throw new IllegalStateException("SHA-256 not available", e);
413	        }
414	    }
415	
416	    /**
417	     * Builds the membership number for a newly created owner, formatted
418	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
419	     * customer code and {@code YY} is the last two digits of the owner's registration
420	     * date year, zero-padded to two digits.
421	     *
422	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
423	     * @param registrationDate the owner's registration date
424	     * @return the assigned membership number (e.g. {@code 'NSW-1A2B3C4D-M26'})
425	     */
426	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
427	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
428	    }
429	
430	    /**
431	     * Counts how many existing owners share the given first and last name, compared
432	     * case-insensitively. This is evaluated before the new owner is persisted, so the
433	     * owner being created is not included in the count.
434	     *
435	     * @param firstName the new owner's first name
436	     * @param lastName  the new owner's last name
437	     * @return the number of existing owners with the same first and last name
438	     */
439	    private int countNamesakes(String firstName, String lastName) {
440	        int count = 0;
441	        for (Owner existing : this.clinicService.findAllOwners()) {
442	            if (firstName.equalsIgnoreCase(existing.getFirstName())
443	                && lastName.equalsIgnoreCase(existing.getLastName())) {
444	                count++;
445	            }
446	        }
447	        return count;
448	    }
449	
450	    /**
451	     * Canonical expansions applied to common street-type abbreviations during address
452	     * normalization. Keys and values are upper-cased so the lookup runs after the address
453	     * has itself been upper-cased.
454	     */
455	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
456	        "ST", "STREET",
457	        "RD", "ROAD",
458	        "AVE", "AVENUE");
459	
460	    /**
461	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
462	     * every run of internal whitespace is collapsed to a single space, the result is
463	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
464	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
465	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
466	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
467	     * returned and compared for household duplicates; an address that is blank once
468	     * normalized fails the required-field check.
469	     *
470	     * @param address the raw address value supplied by the client
471	     * @return the normalized address (empty string when {@code address} is null or blank)
472	     */
473	    private static String normalizeAddress(String address) {
474	        if (address == null) {
475	            return "";
476	        }
477	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
478	        if (collapsed.isEmpty()) {
479	            return "";
480	        }
481	        StringBuilder normalized = new StringBuilder(collapsed.length());
482	        for (String token : collapsed.split(" ")) {
483	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
484	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
485	            if (normalized.length() > 0) {
486	                normalized.append(' ');
487	            }
488	            normalized.append(expanded != null ? expanded : token);
489	        }
490	        return normalized.toString();
491	    }
492	
493	    /**
494	     * Normalizes a last name or address for household-duplicate comparison: leading and
495	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
496	     * single space and the result is lower-cased. Two owners are considered to share a
497	     * household when both their last names and addresses produce the same key.
498	     *
499	     * @param value the raw last name or address value
500	     * @return the normalized comparison key (empty string when {@code value} is null)
501	     */
502	    private static String householdKey(String value) {
503	        if (value == null) {
504	            return "";
505	        }
506	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
507	    }
508	
509	    /**
510	     * Derives the stable shared household identifier for the given normalized last name
511	     * and address keys. The identifier is deterministic — the same household (same
512	     * {@link #householdKey normalized} last name and address) always maps to the same
513	     * value — so every owner who joins a household is assigned an identical id. It is the
514	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
515	     * '<lastNameKey>|<addressKey>'}.
516	     *
517	     * @param lastNameKey the normalized last name key
518	     * @param addressKey  the normalized address key
519	     * @return the shared household identifier
520	     */
521	    private static String householdId(String lastNameKey, String addressKey) {
522	        String source = lastNameKey + "|" + addressKey;
523	        try {
524	            byte[] digest = MessageDigest.getInstance("SHA-256")
525	                .digest(source.getBytes(StandardCharsets.UTF_8));
526	            StringBuilder hex = new StringBuilder(digest.length * 2);
527	            for (byte b : digest) {
528	                hex.append(String.format("%02x", b));
529	            }
530	            return hex.substring(0, 12).toUpperCase();
531	        } catch (NoSuchAlgorithmException e) {
532	            throw new IllegalStateException("SHA-256 not available", e);
533	        }
534	    }
535	
536	    /**
537	     * Builds the derived duplicate-detection identity key from an owner's normalized
538	     * telephone, email and household id, formatted {@code
539	     * '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Two owners are
540	     * duplicates only when their whole identity keys are equal; because the telephone is
541	     * part of the key, members of the same household with different telephones produce
542	     * different keys and are both allowed.
543	     *
544	     * @param normalizedTelephone the E.164 telephone (may be {@code null})
545	     * @param email               the normalized (lower-cased) email, or {@code null} when absent
546	     * @param householdId         the shared household id, or {@code null} when the owner is not in a household
547	     * @return the identity key string
548	     */
549	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
550	        return (normalizedTelephone == null ? "" : normalizedTelephone)
551	            + "|" + (email == null ? "" : email)
552	            + "|" + (householdId == null ? "" : householdId);
553	    }
554	
555	    /**
556	     * Normalizes an existing owner's stored email for identity-key comparison: trimmed and
557	     * lower-cased, mirroring {@link #normalizeEmail} without re-validating syntax. Returns
558	     * {@code null} when the owner has no email.
559	     *
560	     * @param email the existing owner's stored email (may be {@code null})
561	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is null
562	     */
563	    private static String emailForKey(String email) {
564	        return email == null ? null : email.trim().toLowerCase();
565	    }
566	
567	    /**
568	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
569	     * and brackets are stripped. When the number already carries a leading {@code '+'}
570	     * and country code these are kept; a number written in national trunk form (a leading
571	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
572	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
573	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
574	     * after the {@code '+'}, and its national-number length must be valid for the detected
575	     * country code (see {@link #hasValidNationalLength}).
576	     *
577	     * @param telephone the raw telephone value supplied by the client
578	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
579	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
580	     */
581	    private static String toE164(String telephone) {
582	        if (telephone == null) {
583	            return null;
584	        }
585	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
586	        String digits;
587	        if (cleaned.startsWith("+")) {
588	            digits = cleaned.substring(1);
589	        } else if (cleaned.startsWith("0")) {
590	            digits = "61" + cleaned.substring(1);
591	        } else {
592	            digits = "1" + cleaned;
593	        }
594	        if (!digits.matches("[0-9]{8,15}")) {
595	            return null;
596	        }
597	        if (!hasValidNationalLength(digits)) {
598	            return null;
599	        }
600	        return "+" + digits;
601	    }
602	
603	    /**
604	     * Validates the national-number length of an E.164 digit string against its country
605	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
606	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
607	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
608	     *
609	     * @param digits the E.164 digits (without the leading {@code '+'})
610	     * @return {@code true} when the national-number length is valid for the country code
611	     */
612	    private static boolean hasValidNationalLength(String digits) {
613	        if (digits.startsWith("61")) {
614	            return digits.length() - 2 == 9;
615	        }
616	        if (digits.startsWith("1")) {
617	            return digits.length() - 1 == 10;
618	        }
619	        return true;
620	    }
621	
622	    /**
623	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
624	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
625	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
626	     */
627	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
628	        "NSW", new int[] {2000, 2099},
629	        "VIC", new int[] {3000, 3099},
630	        "QLD", new int[] {4000, 4099});
631	
632	    /**
633	     * Validates an owner's postcode for creation. A postcode is only ever validated when
634	     * present (an absent postcode is optional and accepted). When present it must be exactly
635	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
636	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
637	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
638	     *
639	     * @param postcode the supplied postcode (never {@code null} here)
640	     * @param city     the owner's city, used to derive the region
641	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
642	     *         (signalling a 400 Bad Request)
643	     */
644	    private static boolean isValidPostcode(String postcode, String city) {
645	        if (!postcode.matches("[0-9]{4}")) {
646	            return false;
647	        }
648	        int[] range = REGION_POSTCODES.get(
649	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
650	        if (range == null) {
651	            return true;
652	        }
653	        int value = Integer.parseInt(postcode);
654	        return value >= range[0] && value <= range[1];
655	    }
656	
657	    /**
658	     * Normalizes an owner email for creation. A present email must be a syntactically
659	     * valid address; the returned value is lower-cased.
660	     *
661	     * @param email the raw email value supplied by the client (never {@code null} here)
662	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
663	     *         address (signalling a 400 Bad Request)
664	     */
665	    private static String normalizeEmail(String email) {
666	        String trimmed = email.trim();
667	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
668	            return null;
669	        }
670	        return trimmed.toLowerCase();
671	    }
672	}
